    11	    if (iouAction === CONST.IOU.ACTION.CATEGORIZE || iouAction === CONST.IOU.ACTION.SUBMIT || iouAction === CONST.IOU.ACTION.SHARE) {
    12	        Navigation.goBack();
    13	        return;
    14	    }
    15	    // If the participants were automatically added to the transaction, then the user needs taken back to the starting step
    16	    switch (requestType) {
