    18	            Navigation.goBack(ROUTES.MONEY_REQUEST_CREATE_TAB_DISTANCE.getRoute(CONST.IOU.ACTION.CREATE, iouType, transactionID, reportID));
    19	            break;
    20	        case CONST.IOU.REQUEST_TYPE.SCAN:
